","
ヒトでは組替えを利用する古典的な遺伝子の地図作成は大変困難である。
兄弟の数が少ないこと、交配を自由に支配できないこと、一生が長いこと、
遺伝子の多くは頻度が低いことなどが組み合わさって、
ヒトでは連鎖検定がきわめて困難である。

自分自身の属する種だという特別の興味がなかったとしたら、
ヒトの染色体地図をつくろうとすることなどずっと以前にあきらめていただろう。

（遺伝学概説 第8版(1991) / J.F. クロー 著 / 木村資生・太田朋子訳）
","
自然はあまりにも複雑なので、それを完全に記述したり理解する事はできない。
したがって、われわれはその特別な面にだけ興味をもつのが普通である。

（遺伝学概説 第8版(1991) / J.F. クロー 著 / 木村資生・太田朋子訳）
","
近年、情報革新によって計算機の記憶媒体の容量が飛躍的に増大し、
しかも価格が急落したため、データを溜め込むことが容易になった。
一昔前のように、文字データだけというのではなく、
映像でも、画像でも、音声でも、かなり自由に溜めることができる。

しかもインターネットをはじめとして通信技術が進歩したため、
自分のところにデータばかりではなく、他所にあるデータ、海外にあるデータでも、
容易に取り出してみることができる。

ただし、データはやみくもに溜めても使えない。
それぞれの仕事に応じて使いやすい形なっていなければ、ただのゴミである。

（混雑と待ち(2001) / 高橋幸雄・森村英典 著）
","
昔は膨大な労力をかけて使いやすいデータベースを構築した。
最近は何でも溜められるものだから、この努力が薄れてきている。

（混雑と待ち(2001) / 高橋幸雄・森村英典 著）
","
また人工知能や統計学を利用したデータマイニングを行うソフトウェアも出されている。
しかし質の悪いデータからは質の悪い結果しか出てこない。
粗悪な材料から美味しい料理は作れないのである。

今後、データベースの質を向上させそれを腐らせないよう維持するための努力を重ねるとともに、
その努力を正当に評価する習慣を育てていかなければなるまい。

（混雑と待ち(2001) / 高橋幸雄・森村英典 著）
