関口さん、ぼくらは、ちょっとですが、疲れたんです。市場というものがどういうものか少しわかりました。
市場というのは、欲望をコミュニケートする場所で、まるで空気みたいに、
あるいはウイルスみたいに、どこにでも入り込んできて、それまでそこにあった共同体を壊してしまうんです。
