(「希望の国のエクソダス」 / 村上龍 著)
","
でも、このプランはうちの弁護士や経営者や投資顧問にはまだ話していません。彼らが考えているのは利潤のことだけなので、まだどういう反応をするのかわからないんです

(「希望の国のエクソダス」 / 村上龍 著)
","
ただ、ぼくらはそういう市場を利用して資金を作ったし、大人の社会と戦ったわけなんだけど、
そのルールにずっと従うのはばかばかしいと思うようになったんですよ。
もちろん市場はニュートラルだから、市場が悪いわけではなくて、市場が生み出す不均衡が悪なんです。
自由主義経済は必ず敗者を生むから、勝者も敗者からの復讐を怖れて生きなくてはいけないでしょ？
それって、本当に無駄だと思いません？
DVDプレーヤーを買ってくれなかったからといって母親をバットで殴り殺した中学生がいたでしょう？
それに売春する女子中学生もたくさんいたでしょ？
臓器を売るホームレスもいるし皮膚を売る大学生もいたでしょう？
あれはぼくらの生活の隅々に市場が入り込んでいて、
臓器やからだといったもともとは個人に属しているはずのものまでが売買の対象になっているということなんです。
このままでは、ぼくらは、ぼくらが憎んだ大人とちっとも変わらない大人にしかなれないと思ったわけなんです。

(「希望の国のエクソダス」 / 村上龍 著)
","
もちろん市場はニュートラルだから、市場が悪いわけではなくて、市場が生み出す不均衡が悪なんです。
自由主義経済は必ず敗者を生むから、勝者も敗者からの復讐を怖れて生きなくてはいけないでしょ？
