","
自分が今、生きてる外側にちょっと面白いことがあると思ってないとさ。

(「希望の国のエクソダス 取材ノート」 / 村上龍 著)
","
村上「ウォール街の証券取引所に行ったら、いっぱいモニタが並んでて、「ゲームセンターみたいだ」と思ったんです」
松田「でも、実際にやってみると、これはほんとにゲームですよ。
　　　僕は、会社に入って、英語も喋れないままニューヨークに行かされたんです。すぐにディーリング・ルームに入れられて、
　　　お前、これやれって感じで。「売った買った」とやらされた。で、三日目に、これは要するに博打だとわかったんです。」

(「希望の国のエクソダス 取材ノート」 / 村上龍 著)
","
コープの法則の述べている事実は正しい。
しかし、この事実だけを聞くと「定向進化説」や「大きいことはいいことだ説」という誤った考えに陥りやすい。
科学というものは自然の一面だけを切り取ってきて考えるという性癖をもっている。
一面だけの事実が指し示す方向が、必ずしも正しい方向ではないことを、いつも忘れないようにしたいものだ。

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
学校にあがってまず習ったことの一つに、時間とは時計で測るもので、腹がへったら勝手にお昼、とはならないということがあった。
自分がどう思う、どう感じるなどとは関係なく決まった時間があって、これには人間のみならず、虫も花も獣もそして無機の自然も、すべてがしたがわねばならぬものである。
そういう超越的絶対者が時間というものだ、と教え込まれた気がする。
始業のベルは、なんとなく権威の響きがあった。

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
ヒトはほとんど目に頼って生きており、目を通してまわりの世界を頭の中に再構成している。
感覚が発達していない事象に関しては、たとえ外界に存在していても、ヒトの頭の中の世界には存在しない。
もちろん、ヒトには時間の感覚はある程度はある。
だから、この再構成された世界に時間軸は存在するのだが、ヒトの時間感覚は外部の時間を俊敏に計れるものではなさそうで、そのため、たぶん、頭の中の時間軸は、自分に固有の時間軸しかないのであろう。
時間に関しては、ヒトは外部には閉ざされた存在だと言えるのではないか。
だからこそ、時間は絶対普遍なものだと信じ込みやすいのだろう。
もしヒトがもっと時間感覚の発達した生き物だったら、対象物にあわせていろいろな時間軸を設定でき、世界をもっと違った「目」で「見ていた」はずである。
時間と空間の関係式も、簡単に「発見」できたに違いない。

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
おのおのの動物は、それぞれ違った世界観、価値観、論理を持っているはずだ。
たとえその動物の脳味噌の中にそんな世界観がなくても、動物の生活のしかたや体のつくりの中に、世界観がしみついているに違いない。
それを読解し、ああ、この動物はこういう生活に適応するためにこんな体のつくりをもち、こんな行動をするのだなと、その動物の世界観を読み取ってやり、人間に納得のいくように説明する、それが動物学者の仕事だと思うようになった。

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
近ごろ、外国との摩擦のニュースを聞くにつれ、違う世界観を理解することの難しさがよく分かる。
同じ人類の間でそうなのだから、違う動物の世界観を理解することなど、よほどの努力を払わなければできないことである。
しかし、その努力をしなければ、決して人間はさまざまな動物を理解し、彼らを尊重できるようにはならない。

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
私たちの常識の多くは、ヒトという動物がたまたまこんなサイズだったから、そうなっているのである。
その常識を何にでも当てはめて解釈してきたのが、今までの科学であり、哲学であった。
哲学は人間の頭の中だけを覗いているし、物理や化学は人間の目を通しての自然の解釈なのだから、人間を相対化することはできない。
生物学により、はじめてヒトという生き物を相対化して、ヒトの自然の中での位置を知ることができる。

今までの物理学中心の科学は、結局、人間が自然を搾取し、勝手に納得していたものではなかったのか？

（ゾウの時間　ネズミの時間　サイズの生物学 / 本川達雄 著）
","
> 『存在しないはずの8月32日、終わらない夏休み、壊れていく世界』という偶然生まれた独特の世界観

（Wikipedia 「ぼくのなつやすみ」 <a href=\"https://ja.wikipedia.org/w/index.php?title=%E3%81%BC%E3%81%8F%E3%81%AE%E3%81%AA%E3%81%A4%E3%82%84%E3%81%99%E3%81%BF&oldid=22415275\">2018年10月19日版</a>）
","
アノ地球《ホシ》ヲ、コワスタメ。

（「R-TYPE LEO」 / IREM 1992）
","
敵は地球、未来の人類。

（「サンダーブラスター」 / IREM 1991）
","
多くの生徒たち、とくに貧困な生徒たちは、学校が彼らに対してどういう働きをするかを直感的に見抜いている。彼らを学校に入れるのは、彼らに目的を実現する過程と目的とを混同させるためである。過程と目的の区別が曖昧になると、新しい論理がとられる。手をかければかけるほど、よい結果が得られるとか、段階的に増やしていけばいつか成功するとかいった理論である。

（脱学校の社会 / イヴァン・イリイチ 著 / 東洋・小澤周三 訳）
","
このような論理で「学校化(schoooled)」されると、生徒は教授されることと学習することとを混同するようになり、同じように、進級することはそれだけ教育を受けたこと、免状をもらえればそれだけ能力があること、よどみなく話せれば何か新しいことを言う能力があることだと取り違えるようになる。

（脱学校の社会 / イヴァン・イリイチ 著 / 東洋・小澤周三 訳）
","
彼の想像力も「学校化」されて、価値の代わりに制度によるサービスを受け入れるようになる。医者から治療を受けさえすれば健康に注意しているかのように誤解し、同じようにして、社会福祉事業が社会生活の改善であるかのように、警察の保護が安全であるかのように、武力の均衡が国の安全であるかのように、あくせく働くこと自体が生産活動であるかのように誤解してしまう。
健康、学習、威厳、独立、創造といった価値は、これらの価値の実現に奉仕すると主張する制度の活動とほとんど同じことのように誤解されてしまう。そして、健康、学習等が増進されるか否かは、病院、学校、及びその他の施設の運営に、より多くの資金や人員をわりあてるかどうかにかかっているかのように誤解されてしまう。

（脱学校の社会 / イヴァン・イリイチ 著 / 東洋・小澤周三 訳）
","
メキシコでは、十年前には、自分の家で生まれ、自分の家で死に、そして自分の友達によって葬られるというのは普通のことであった。制度としての教会のお世話になるのは、霊魂の必要とするものに限られていた。それが現在では、自分の家で人生を始め、かつ終わるというのは、貧困かあるいは特別な特権かどちらかのしるしである。臨終と死は、意思と、葬儀屋の制度的な管理のもとに置かれるようになった。

（脱学校の社会 / イヴァン・イリイチ 著 / 東洋・小澤周三 訳）
","
誰もが、学校の外て、いかに生きるべきかを学習する。
我々は、教師の介入なしに、話すこと、考えること、愛すること、感じること、遊ぶこと、呪うこと、政治にかかわること、および働くことを学習するのである。日夜、教師の保護のもとにある子供でさえも、この法則の例外ではない。孤児も知恵おくれも、また教師の息子も、彼らが学ぶことの大部分を彼らのために計画された「教育」の過程の外で学ぶのである。

