","
余剰価値が発生するのが労働の現場だとしても、それが実現するのは販売されてのことである。商品は売れなければ余剰価値も実現できない。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
これはおそらく、未開社会を含めてほとんどあらゆる社会についていえることで、ほんの例外的なケースを除いて、一般的に人間社会は基本的生存水準以上の生産力を持っているのである。その意味では生産はつねに「過剰」なのだ。だからこう考えれば、人間社会の経済問題は「希少」にあるのではなく、むしろ「過剰」にあるというべきではなかろうか。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
こうして過剰なものの蕩尽は、それが皆の前で誇示され見せびらかされることによって、世俗的な権力や権威へと転化する。そうすることによって、それは人々の社会的な位置を確定して社会の秩序を保つ役割を果たすのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
近代経済学者たちは、モノを買う側の「効用」こそが重要だということに気づきながらも、その効用がどうして形成されるのか、ある人にとっての効用と彼の住んでいる社会にはどのような関係があるのか、といったことは全く問題にしなかった。それはただ分析の上の「与件」とされたのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
もちろんこのマズローの欲望段階説はにわかには受け入れがたい。そもそも欲望が、このようにきれいに五つに分かれるはずはないし、それが段階を追って高次元化するとは考えがたいからである。だがいまそれらを、仮に認めるとしても、やはり納得できない点がある。それは、マズローが、あたかも欲望があらかじめ個人の中にあるかのように論じている点であり、そもそもそうした欲望がどのように発生するかを説明できない点である。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
欲望の充足は、また社会的優越と不可分なのであり、実際上、欲望は、純粋に対象に向けられたものというより、こうした仲間の間での優位をめぐる競争と切り離せなくなる。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
欲望が、それを容易には獲得できないという「距離」によって条件付けられているとすれば、欲望はますます、手にはいりにくいものに向かうだろう。だからそれは、日常のものより非日常なものに向かうだろうし、めずらしいもの、得がたいもの、新奇なものへとたえず向かうだろう。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
人間は常に意味を求め、観念を生み出す動物である。人はほんのちょっとしたモノの中にさえ意味や観念を見いださなければ気がすまないのだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
モノは必ずある文明や文化の所産なのである。だからモノにはそれが生み出された国や地方の文化の刻印が必ず押されているものだ。そこにモノの象徴作用があり、だからこそモノは勝ちを持つ。アジアの産物はヨーロッパ人にとっては、東方の神秘を宿したものであった。ヨーロッパの「欲望」は結局のところ、こうした「東方的なもの」に向けられていたのである。東洋の物産は、その代理と象徴にすぎなかった。しかし、この代理する（リプリゼント）ということこそが文化の本質なのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
「消費」はいつの時代もイメージの消費なのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
２０世紀の初めにアメリカにわたってきた移民たちは、まず「アメリカ市民」になろうとした。アメリカ市民であるということは、それらしく見えることである。郊外住宅に住み、守るべき財産と家族を持つことであり、物事を民主的かつ合理的に考えられることであった。商品と結びついたデザインや広告は、この「アメリカ市民」らしくみせるにはどうしたらよいかに対する精神安定剤となった。消費は一種のサイコ・セラピーの役割を果たすのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
人は結局、一人で生きているものではないし、社会から切り離されて欲望の確かな対象をもてるものでもない。欲望を突き動かすパッションは、いつもしかとは捕えがたいあいまいとしたものである。それに具体的な形をあたえるのは、たいていの場合、前にも述べたように、社会的な条件なのである。他人の存在が欲望の基本的な条件なのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
他人が欲するものを欲する。他人がほしがっている手に入りにくいものを欲しがるというのは、欲望のごく普通の姿だ。だから、欲望の充足である消費は、「他人のまなざし」を必要とする。消費は他人に見てもらう必要がある。この意味で欲望の充足は本質的に社会的なことなのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
モノをもつことが人生の証しであり、地位の証明であり、「アメリカ人」になることだったのである。あるいはモノを介して他人からそのように認められることだったのである。だからモノはアメリカン・ドリームを象徴するものだったのだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
モノによってしか、自分をアイデンティファイできないのが現代の大衆なのである。自動車・ファッション・住宅といったモノに託して自分を他人の眼差しにさらし、そのことによって自分を肯定してもらう、このようにしてしかセルフ・アイデンティティを確認できないのが大衆社会なのだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
人々は、モノを買うことによって、自分自身をいわば鏡にに映すようにみようとしている。本当に関心があるのは、モノそれ自体というより、それを身につけ、使い、所有する自分自身なのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
「外」の世界に対する強い関心を失って、「外」に欲しいものがなくなったとき、人は自分自身に欲望を向ける。それこそが絶対に手に入らないものだからである。もともと「本当の自分」などというものはどこにもないのだから。だから、消費は、いつまでも続く「わたし探しのゲーム」となる。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
「欲望」は前に述べたように、未知のもの、タブーとされているもの、容易には手にはいらないものへと向かう。だから宗教的情熱も背後にあるのは「欲望」である。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
未知のもの、あるいはタブーを作り出す想像力が、人間のシンボル操作能力に基づくとすれば、この「欲望」もこの想像力の結果なのであり、想像力とパッションが結びついたとき、人は欲望のフロンティアをたえず拡大してゆこうとするだろう。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
未知のもの、手にはいらないもの、そうしたものに対する「欲望」というより、ちょっとした「好奇心」、すぐに飽和し、移り変わっていく「好奇心」が、現代の情報化の時代を支配している。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
未知のもの、手にはいらないもの、そうしたものに対する「欲望」というより、ちょっとした「好奇心」、すぐに飽和し、移り変わっていく「好奇心」が、現代の情報化の時代を支配している。消費者は、メディアが仕掛ける情報によって「好奇心」をくすぐられているだけだ。「好奇心」はいつも小規模なバブルである。しかもそれはすぐにはじけ、また次の対象に移ってゆく。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
そして現代の情報化社会では、資本主義はメディアに依存する。メディアが欲望を操作するといういい方は必ずしも適当ではない。むしろ人々がメディアによって欲望を刺激されることを待っている、といった方が適切だろう。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
資本主義は、その成長のために、あらゆるストックをフロー（流れ）に変えてゆこうとするのだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
要するに、「資本主義」の運動には、合理的に説明できる根拠もないし、また目的もないということだ。一種の盲目的な自己拡張があるだけだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
こうして、言葉はリアリティを失ってゆく。言葉は、リアリティから乖離して、ただ効果だけを狙ったものへとなってゆく。
言葉が、メディア・情報の回路の中で、ただ「好奇心」を刺激するだけで次々と回転してゆくのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
だからバブル現象といったときには、すでにこうした、習慣的に妥当だと思われる水準があるということを暗黙のうちに前提にしているのだ。もうすこし言うと、市場経済の背後には、実は、社会的で習慣的な価値の体系がやはり存在しているのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
銀行券というただの紙切れが、貨幣となったのは、むしろそこに何の特定の使用価値もないからである。貨幣であるためには、具体的な価値をもってはならないのだ。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
市場そのものには、「異常」と「正常」の区別など無いのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
近代人は、知識の領分であれ、技術の領分であれ、ともかくもフロンティアを拡張することに並々ならぬ関心を払ってきた。この拡張が即、進歩であり発展であると考えられた。それはほとんど無条件の発展で、そこに目的などしいて設定することもなかった。たしかに近代人は、「目的無き（エンドレスな）発展」を、「終わりなき（エンドレスな）発展」を、信奉していたのである。

（「欲望」と資本主義 / 佐伯啓思 1993）
","
経済というのはダンスなんだ。
くるくる回るダンス。
つま先がすり切れるまで、命がすりつぶされるまで回り続けるダンス。
楽しいかどうかは問題じゃない。
回ってるかどうかが問題なんだ。
