","
人の命には限りがある。
生きているうちにやれる事はやっておこう……というような、かなり切迫した気分に襲われました。
でも、やりたい事の３分の１もやっていないのに、気がつけばほとんど熟年です。
僕の友人には「100歳まで生きてやる」という人もいますが、僕は無理でしょう。
そもそも、物書きの寿命は、若い頃の不摂生もあってか、そう長くはありません。
とりあえず、書く予定が決まっているものは片づけたいと思っています。
そのひとつがこのコラムです。

