たとえばピアノやバイオリンのような西洋のものだけが音楽として唯一絶対のものと思い込んでいると、日本の琴や笛は雑音にしか思えなくなりますよね。

なんだこのドレミの音階も知らない野蛮な雑音は、とゲラゲラ笑うかも知れません。

