（「ブギーポップは笑わない(2019)」 / 第11話 「夜明けのブギーポップ」）
","
「でも、それはあなただけではなく、すべての人間は皆、世界の敵たりうる可能性を秘めているんだ。
　人間というのは起爆剤のようなもので、ちょっとしたきっかけで、すぐに破裂する。
　そして、後先考えないで、世界を軋ませていく…。
　ぼくは、言うなれば、そういうものの、天敵みたいなものか」
「すべての人間というけど、ほとんどの人は普通だと思うわ」
「普通だから、そうなるのさ」
「…どういうこと？」
「もしも何か特別なものに出会ったとしても、自分を持っている人であれば、それを冷静に受け止められる。
　だが、普通すぎると、その波に飲み込まれ、あとは流されていく。
　そういう暴走が、一番危険なのさ」
「それって正常性バイアスの類かしら」
「さあね。ただ、そういう、『普通なだけでいい』と思っている者には、抵抗力がない。
　そして、彼らが思いこんでいるほど、実は、世界は安定もしていない。
　いつでも危機が。
　そう。その壁を突破することを待望している者にとってのチャンスが、そこら中に転がっている」

