ストックフォトの検索ワードも、SNSのハッシュタグも、プロンプトも、使われる語句は主に名詞だ。ときどき形容詞や「#写真好きとつながりたい」といったようなスローガンも見かけるが、ほとんどは名詞で、動詞は少ない。これは画像に「時間」が含まれていないということだ。ただ存在と状態を示すだけで、動きや変化を思わせるものがない。別の言い方をすると「物語がない」のだ。

