","
宗教は〈愛〉と〈赦し〉を説くが、人を幸せにしない。人類社会を平和にもしない。なぜか。宗教とは人間の勝手な思惑で作られたフィクションに過ぎないからである。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
素晴らしい言葉である。この教えをわれわれが、たった一日でも守れるのなら、たちどころに世界平和が実現する。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
樹木や岩にも精霊を感じ、礼拝するようなアニミズム的宗教を未発達な偶像崇拝と見るのは、超越的一神教特有の救いがたいまでの偏見である。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
その宗教に出会う必要がある魂は、ちょうど必要なときに出会うようにできている。その機会をこちらから、人為的に作る必要は一切ない。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
今も昔も、純粋な宗教戦争などあり得ない。「神」の名において、人間はみずからのもっとも卑劣な欲望を正当化しようとするのである。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
まず「アメリカ教」の総本山がどこにあるのかといえば、アメリカ東海岸のワシントン特別区にあり、その名前をホワイトハウスという。だから、あの建物は教会のように崇高な白色に塗られ、十字架の代わりに高々と星条旗を掲げているのである。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
「アメリカ教」の世界布教のやり方は、グローバリズムという名称で呼ばれているものである。グローバリズムの正体が何かといえば、アメリカ版中華思想であり、いくつもの仮面をかぶった覇権主義である。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
（「アメリカ教」は）どのような神を崇めているかといえば、「富」という神であり、その神に近づくために、アメリカ型の自由と民主主義という「教義」を受け入れなくてはならないとされる。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
つまり、「アメリカ教」の核心にある自由と民主主義というのは、富の格差を基本的条件として認め、近代的個我の栄光を追求するシステムのことなのである。良し悪しは別として、このことをしっかりと認識しておかないと、幻想のアメリカを憧憬してしまうことになる。

（人類は「宗教」に勝てるか / 町田宗鳳）
","
アメリカは「人種のルツボ」といわれるほど、多民族国家であるが、そのことは多元的価値観の社会であることを意味しない。出身国がどこであろうと、「アメリカ教」の信者にならない限り、成功はできない一元的価値観の社会なのである。

