","
どの分野においても、あるレベルを超えた趣味人は多かれ少なかれ、こうした満たされない思いを常に抱いているはずだ。絶対的な存在に対し、それを渇望し、ただ祈る。やがて湧き上がる渇望によって、ただ祈るだけの時間に耐えられなくなる ー この段階に達した時、人はみずからそれを生み出すために手を動かし始めるのだ。その世界に存在すらしていない理想の事物にどうしても触れたいというほとんど追いつめられるような気持ちと、そのまだ見ぬものへの果てしない憧れを同時に胸に秘めながらこう決意するのだ。それが世界に存在していないのなら、自分で制作するしかないのだ、と。

