現代にあっては、労働は個人のアイデンティティすら侵食し、働くことを通してしか自己実現を果たすことができない仕事人間を大量に生み出してきた。

（木澤 佐登志, <a href=\"https://gendai.media/articles/-/141666\">「壊れてちゃいけないんだろうか」…外部への接続を阻む資本主義の「透明な檻」</a>）
","
「生産性」というイデオロギーこそは、私たちを囚えているもっとも強固なネットワークかもしれない。抗鬱剤の氾濫は資本主義の延命措置でしかなく、人々を労働に駆り立てる威勢の良い言辞の蔓延とは裏腹にその実、資本主義というシステムが機能不全に陥っていることを暴き出している。

（木澤 佐登志, <a href=\"https://gendai.media/articles/-/141666\">「壊れてちゃいけないんだろうか」…外部への接続を阻む資本主義の「透明な檻」</a>）
","
われわれの知っているバートルビー族というのは、心の奥深いところで世界を否定している人間のことである

（木澤 佐登志, <a href=\"https://gendai.media/articles/-/141666\">「壊れてちゃいけないんだろうか」…外部への接続を阻む資本主義の「透明な檻」</a>）
","
俺を裁くことは不可能です。何故ならオレはライオンだからです。
ライオンが人を殺したとします。
裁判にひっぱっていって、有罪判決にしたとします。
アンタらは悪を裁いたと、正義を守ったと喜びますが、はたしてライオンは裁かれたと感じるでしようか︖
人間側のひとりよがりです。
人間が裁くことが出来る相手は、同じ概念、常識、価値観を共有している人間だけです。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
自殺ができる人種は二種類しかいません。たぶん。
武士みたいな人と絶望してる人です。俺はどちらでもない。自ら直接命は絶てない。
ギロチンのスイッチはあなたが押してくれ。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
死のドコを恐怖すればよいのでしょう︖何故人々は死を怖れるのだろうか︖
「痛み」を恐がるというのならわかりますがね。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
いや、もう高校３年の時に死のうと思っていました。大学に行くつもりはないし、やりたいことがあったわけではないし、この世界でもうやりたいことはないと思いましたから。
ただ高校を卒業してすぐに死ぬというのはどうかと思ったので時間がたっただけです。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
― （裁判記録が全部間違っており、茶番であるという話に対して）でも君が死刑になったとしても裁判記録は残るのだから、君 の考えはきちんと残しておいた方がいいんじゃないの︖
金川「（少し考えて）別にいいです。」

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
俺の事件は、間違 っている記録が「真実」として未来に残されます。バカです。あきれます。でもしかたありません。裁判官も検事も鑑定人も、真実を見ようと、理解しようとしなかったのです。アホです。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
関係ないですが、俺の担当になった荒井刑事は人情派な良い刑事でした（笑）。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
永遠の命、究極の力、限り無き自由、終わらない冒険、どれもこの世界では手に入らなかった。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
こうして生きてることは、時間のムダ、税金のムダ。
法務省の人間を皆殺しにしてやりたいね。
死刑執行は６ヶ月以内。守られていない。
テメエで作った法をテメエで守らないのはバカだ。
どのツラさげて悪人を裁くんだ︖
ＰＳ 福島さんはもし、自分 の家族が誰かに殺されたとしたら、その犯人を許せますか︖
その犯人は死刑にはしたくないと思えるんでしょうか︖
死刑は必要だと思いますけど……。

（金川真大 死刑囚, ドキュメント 死刑囚 篠田博之）
","
青年は、法務大臣が代わるたび
「６か月以内に執行しないのは法律違反だ」
「何で殺さない」
「税金の無駄遣いだ」
と官製ハガキにびっしり書いて送っていた。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
　青年は20歳の頃から、自分の人生に見切りをつけていた。進学も、就職もしたくなかったから、しなかった。でも、自室にいても、何の希望もなく、つまらない日々が過ぎていった。テレビゲームで毎日を埋めていたが、もう限界だった。「死のう」。自殺を考えた。でもよく考えると、自殺はうまくいかないかもしれない。確実に死ねる方法は何だろう？思いついたのが死刑だった。
　綿密に計画を立て、２人を殺し、７人を負傷させて死刑判決を受け、ここまで来た。なぜこんな時間のかかる方法を選んだんだろう。何度も後悔した。確実に死ねる安楽死の制度があるなら、迷わずそれを選んだだろう。
　でも、ようやく、この日が来た。
　執行の日、だ。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「突然、執行すると言われて、怖いと思わないの？」面会に来たそう聞いてきたこともあった。その時は「余裕ですよ」と答えていた。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「時限式にすればいいのに」

（3人で同時に押す死刑執行のボタンについて, 金川真大, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
金川は「死刑のための殺人」を犯した特異な死刑囚だ。１億人もいれば、何年かに１人は出現する。そう言われたこともある。そう言われれば、そうかもしれない。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「すみやかに死刑執行するように。刑法(註: 本来は刑事訴訟法)では6ヶ月以内と決っている（ママ）。が、実際には守られていない。筋が通らない。職責を全うしていない。法を司さどる（ママ）大臣がこれではダメだ」

（日本の司法について言いたいこと(法務大臣へ), 金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「死ぬ覚悟が出来ていない。俺とは違う」

（最近被害者へ謝罪する内容を書いた加藤に対し聞かれて, 金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
全ては運命だ。運命は変えられない。未来は既に決められている。私は、自分の決められた運命を歩み、実行する。この宇宙が誕生した瞬間から、私の運命はこうなると決まっていたのだ。全ては運命だ！！わたしはこの宇宙で最も正しい答えを知っている。私が正義だ！私が法律だ！私の言葉が正しい！私の行動が正しい！私以外の人間は皆、間違っている。

（事件直前に自身の携帯電話へ送ったメール, 金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「（秋葉原事件は）より多く殺している点でうらやましい」「２人より７人の方が罪が重いので」

（金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「死刑じゃないと大変、困ります」

（金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「殺人が悪ではないという考えはいつ頃芽生えた？」
「20歳か21歳ぐらい」
「きっかけは？」
「自分の中で色々考えていて、真実を悟った」
「真実って？」
「ちょー簡単に一言で言うと『何もない』ですね」
「何がきっかけでそう考えたの？」
「高２の時に運命について考えることがあって、それから考えるようになった」
「当時、どんな事を考えた」
「ささいなことですね。SF的な事とか、タイムマシンがあったらとか、考えるようになった」

（金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「生まれてこなければ良かったとは思わない？」
「そうは思わないです」

（金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「こうやって見てると、とても人を殺した人には見えないんだけど」
「それはあなたたちが殺人を大それたものだと思っているから。俺にとっては蚊を殺すのと変わらないですからね」

（金川真大 死刑囚, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
いつだったか、父親が「まっとうな人間とはこういうものだ」とワープロで打ったメモを渡してきたことがあった。世間の考える基準は自分の考えと180度違う。「なに言ってるんだ」と思った。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「私が死ねば、この世界は消滅する。私がこの世界を創造した。この世界は私の世界なのだ。眠りから目覚めることにする。夢は寝ている時の世界。目覚めてしまえば、夢は消える。だから起きることにした」

（事件直前に自身の携帯電話へ送ったメール, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
誰でもいいから殺したい。数を稼がなければならない。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「早く死にたい。早く死にたい。早く死にたい！！　つまらんつまらん。退屈だ。刺激が欲しい。でも手に入らない。この世界じゃね。だから死ぬんだ。退屈な人生歩むくらいなら死んだ方がイイ。ゲームなんかするんじゃなかった。もっと早くやってればよかった。そうすりゃとっくに死ねてた。ゲーム優先しすぎた。７年前に決意してたのに。欲を出しすぎた。たとえ真実を悟っていなくても、なんとかなっただろう。あと１人、死ななくてはいけない。最低でも、あと１人。オレか？オマエラか？あと１人！！」

（2人を殺害しただけでは死刑にはなれないのではという不安について, 金川真大 被告,
  死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
彼を死刑にしてほしい、という被害者や遺族の調書に対しても、
「拍手を送りたかったです」

（金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
ー 痛くない方法を調べることもできたはずです。自殺を具体的に検討したことはあるんですか？
「ないです。そういう情報はあやふやです」

（弁護士からの質問に, 自殺について, 金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
ー 24年間、現実世界で生きてきて、本当に面白いか調べつくしたの？
「いいえ。理想の世界と比べれば、現実はつまらないです」

（弁護士からの質問に, 金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
ー ファンタジーの世界を知っていても、今、生きている世界が楽しいと、どうして思えないの？
「冒険がしたいですね」
ー すればいいじゃん。
「できません」
ー なぜ？
「まず魔法が使えないし、世界地図があります。出発する前から行き先が分かるので」
ー 行ってみたら、いいことがあるかもしれないじゃない？
「たかがしれています」

（弁護士からの質問に, 金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
「グーグルアースもあるし、今はどんな風景でも見える。行き先が分かる、そんな世界では冒険にならない」

（金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
単につまんないから人生やめるかって。軽い感じです。

（幼馴染に殺害動機を聞かれて, 金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
完全勝利といったところでしょうか。

（己の死刑判決について, 金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
社会には、被告人と同様に生きる希望を失い、かといって自殺することもできない、と考えて苦しんでいる人が少なからず存在すると推測します。潜在的な死刑志願者に対し、「死刑になりたいという理由で無差別殺人をすれば、死刑に処される」というメッセージを送れば、そのメッセージに従い、犯行を模倣する者が生じる恐れがあります。予防の見地からすると、被告人を死刑にするのはむしろ逆効果です。

（死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
（記者）「生きる意味って何だと思う？」
（金川）「ないです。もともと（生きる意味が）ないです」

（金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
（金川）「これで悪を裁けたと思いますか？」
（記者）「思わないね」
（金川）「ははっ！」

（金川真大 被告, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
やはり、（ゲームなどのキャラクターを好む）二次元の人で、現実には興味がないのかな、と思いましたね。

（金川真大 死刑囚 について, 死刑のための殺人―土浦連続通り魔事件・死刑囚の記録―）
","
世界のピースが何個か足りない。でも何個かわからない。
","
世界のピースが何個か足りないことは分かるのに、何個かは分からないし、どこかも分からないし、それが何色かもわからない。
","
人に似て、人とは違うーー魔法に愛された者達が宴を開く。

（魔女の愛し仔 / 綾里けいし）
","
「私には、きっと、『人と過ごす』ということが、よくわかっていないんだ」

（魔女の愛し仔 / 綾里けいし）
","
何せ、エンゲル・ヘクセンナハトは生きることに飽きている。

（魔女の愛し仔 / 綾里けいし）
","
この子がいなくなったら、私は毎日の長い時間をどう過ごせばいいって言うんだ。ただでさえ、やることなんてないんだぞ。

（魔女の愛し仔 / 綾里けいし）
","
あぁ、神様…駄目か。貴方は魔女を助けてはくれないな、畜生！

（魔女の愛し仔 / 綾里けいし）
","
「なんで心配をしてくれたんですか？」
「君がいないと退屈になるんだ。私はそれが嫌だと思った……実に、自分勝手だろう？」
「勝手、かはわかりませんが、あの、ご主人様……私達」
「なんだい？」
「本当は、自分達で思ってるよりも、ずっと親しいのではないでしょうか？」

（魔女の愛し仔 / 綾里けいし）
","
愚かだったのよ…
小さな手のひらで救える人間なんて、高が知れている。
こんな大勢の人たちを、幸せにすることなんてできない。

（TRICK（第1シリーズ、2000年） / エピソード1「母之泉」第三話「母の死」）
","
「用が無いなら帰ってください」
「あのねぇ、用があるから来たんだ」
「じゃあ、なおさら帰ってください」

（TRICK（第1シリーズ、2000年） / エピソード2「まるごと消えた村」第一話「村人が全員消えた」）
","
「文字にはねぇ、不思議な力があるの」

（TRICK（第1シリーズ、2000年） / エピソード2「まるごと消えた村」第一話「村人が全員消えた」）
","
「文字には、不思議な力があります」

（TRICK（第1シリーズ、2000年） / エピソード5「黒門島」第二話「真犯人はお前だ!!」）
","
っはは、魔女もお金は要るからな。
まあ、花を飾るくらいには、裕福な客が多いんだろう。
取れるところから、少し取らせてもらうだけだ。

（「<a href=\"https://www.dlsite.com/home/work/=/product_id/RJ01066532.html\">ヴェルディグリは緑青に</a>」 / 和風すくろーる）
","
人のほとんどは死に、自然の多くは朽ち、空に残るのは仄かな光。

（「<a href=\"https://www.dlsite.com/home/work/=/product_id/RJ270846.html\">ここから始まらない幸せ</a>」 / 和風すくろーる）
","
だいたいわれわれSF共同体では、自分たちの商っているものが<ruby>小<rp>(</rp><rt>・</rt><rp>)</rp>説<rp>(</rp><rt>・</rt><rp>)</rp></ruby>であると、できる限りひんぱんに人々に思い起こさせねばならないことくらい、誰もが礼儀としてわきまえている。
ところが世の中には、我々の閉鎖的な仲間内の誰よりもはるかに影響力と権威のある立場にいながら、こうした区別を強調できない ー というより、私の見解ではしたがらない ー 人々が驚くほどいるのである。

（<a href=\"https://dl.ndl.go.jp/pid/12443233/1/55\">解放されたSF : SF連続講演集(1981)</a> / ピーター・ニコルズ 編）
","
人は自らカモとなったり、喜んで共犯者となることが実に多く、いったんそうなると自分の趣味にあって信じ込んでいる事柄に反対の証拠を突き付けられても、無視するか軽んじてしまう。

（<a href=\"https://dl.ndl.go.jp/pid/12443233/1/68\">解放されたSF : SF連続講演集(1981)</a> / ピーター・ニコルズ 編）
","
キャラクターたちを描くことは私にとって、彼(彼女)らに会いに行き、帰ってきてからその様子を忘れないうちに描きとめておく、そんな感覚に近くて、また楽曲や効果音を制作することも同じく、あちらへ赴いて眺める景色を記録するような、そういった作業です。

（永田大祐 / <a href=\"https://camp-fire.jp/projects/798386/view\">ゲームソフト『カラス』を、Nintendo Switchに移植</a>）
","
「何故　何故そこまで私に優しくしてくれるのですか
　私は恩人であるあなたを拒絶し
　罵倒までして勝手に飛び出していきました
　非難されこそすれ　謝っていただく筋合いなど…
　ましてこのように　気にかけていただくなんてー」
「何故って
　あなたが困ったっている顔をしていたから」

（魔法使いロゼの佐渡ライフ 1 / おみなえし）
","
私は今まで　民のためにたくさん尽くしてきました
ですが　ただの一度も私を認めてはもらえなかった

そしていつの間にか私自身が嫌っていたものになってしまっていました…

（魔法使いロゼの佐渡ライフ 1 / おみなえし）
","
私は、私のために戦う。それだけ！

（ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います
 / 第8話 「ふがいない回復役ですが、私のできることを全うしようと思うのです」）
