","
輝ける青春や、絶対的な純粋さなんてものはこの世のは存在しない。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
もともと神なきところで共同体が焼失した社会では、システムが複雑化すればするほど、何が良きことなのか、もはや誰にも自明ではなくなってくる。もちろんそういうなかでも、良きことをしたい、良き人間になりたい人たちは、たくさんいる。しかしながら彼らは簡単なトリックで、「偽物の父親」が指し示す「良きこと」を、少しも自明ではないのに信じ込んでしまう。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
彼らはおそらく、自意識を放棄した解放感を味わいたいのだ。
それが大切すぎるために重くてしんどくて、社会に適応する形に彫りこんでいく作業もまた、不純で薄汚く思えるのだ。
だから、できることなら捨ててしまいたい。
恋愛やスポーツや適当な不良ごっこで、何とか乗り切る者もいる。
でも、一番ラクなのは、他人に自我を明け渡すことだ。
麻原に自我を明け渡した若者たちは、自らのプライドの高さ、それを捨てることのできない自己愛の重みに、絶望していたのかもしれない。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
「終わらない日常」を生きるとは、スッキリしない世界を生きることだ。何が良いのか悪いのか自明でない世界を生きることだ。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
そのような過剰な単純化や一般化は、実は、現実にはありえないような架空の条件を夢想すること抜きにしては、ありえないものだ。確かに、認識にもコストがかかる。環境を認識するとき、できるだけ低いコストで認識したいというのは、理由のあることである。社会システムが複雑になればなるほど、人々（各人格システム）は、コストの低い認識方法の方に集まってくる。人々は認識するために生きているわけではないからである。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
簡単にいえば、戦争にもいろいろな側面があるということだ。それは売春にもいろいろあるし、宗教にもいろいろあるというのと同じである。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）
","
低い分析コストや結果の明晰さに惹かれる気持ちはよく分かるが、それは「複雑な社会を生き抜く知恵」としては最悪である。

（終わりなき日常を生きろ: オウム完全克服マニュアル / 宮台 真司）[
